# This formula is regenerated by the ankra-cli release workflow from
# packaging/homebrew/ankra.rb.tmpl in ankraio/ankra-cli. Manual edits here
# will be overwritten on the next release; change the template instead.
#
# There is deliberately no `version` stanza: `brew audit` fails a tap whose
# declared version it can already scan from the stable URL (redundant_version),
# and every release URL below carries the tag. That is why the URLs interpolate
# nothing - the release workflow substitutes the version into them directly.
class Ankra < Formula
  desc "Command-line interface for the Ankra Kubernetes platform"
  homepage "https://ankra.io"
  license "Apache-2.0"

  livecheck do
    url :stable
    strategy :github_latest
  end

  on_macos do
    on_arm do
      url "https://github.com/ankraio/ankra-cli/releases/download/v0.45.0/ankra-cli-darwin-arm64"
      sha256 "79b01e1a803171e5bf902b399389745a5654694f09df7aa15c8970bcb6240fff"
    end
    on_intel do
      url "https://github.com/ankraio/ankra-cli/releases/download/v0.45.0/ankra-cli-darwin-amd64"
      sha256 "8a0c73b073a094c6b88a5ec3fabfe3c148da4e89e2b7e324187c02abf6957ba0"
    end
  end

  on_linux do
    on_arm do
      url "https://github.com/ankraio/ankra-cli/releases/download/v0.45.0/ankra-cli-linux-arm64"
      sha256 "87d8e388df564c3c352c85c589bbfad2512fd8117451ca21534e68a989051e5a"
    end
    on_intel do
      url "https://github.com/ankraio/ankra-cli/releases/download/v0.45.0/ankra-cli-linux-amd64"
